<?php namespace App\Http\Controllers;use App\Models\User;use App\Models\Store;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\Hash;class AuthController extends Controller{public function showLogin(){return view('auth.login');}public function showRegister(){return view('auth.register');}public function register(Request $r){$d=$r->validate(['name'=>'required|max:100','email'=>'required|email|unique:users','password'=>'required|min:8|confirmed','username'=>'required|alpha_dash|max:40|unique:stores']);$u=User::create(['name'=>$d['name'],'email'=>$d['email'],'password'=>Hash::make($d['password'])]);Store::create(['user_id'=>$u->id,'username'=>strtolower($d['username']),'display_name'=>$d['name'],'published'=>true]);Auth::login($u);return redirect()->route('dashboard.index');}public function login(Request $r){if(!Auth::attempt($r->validate(['email'=>'required|email','password'=>'required']))){return back()->withErrors(['email'=>'Invalid credentials.']);}return redirect()->intended(route('dashboard.index'));}public function logout(Request $r){Auth::logout();$r->session()->invalidate();return redirect('/');}}